import{_ as a,o as t,c as s,an as n}from"./chunks/framework.B2M8tloE.js";const h=JSON.parse('{"title":"metaLines","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/metalines.md","filePath":"concepts/metalines.md","lastUpdated":null}'),o={name:"concepts/metalines.md"};function i(l,e,c,d,r,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="metaLines" tabindex="-1">metaLines <a class="header-anchor" href="#metaLines" aria-label="Permalink to &quot;metaLines {#metaLines}&quot;">​</a></h1><p>A metaLine is an ordinary Julia comment with one extra character: it starts with <code>#~</code> instead of <code>#</code>. That single sigil turns the line into metadata your tools can read — a label, a condition, a visibility action — while Julia sees nothing but a comment.</p><p><code>#~</code> is the <code>:julia</code> flavor&#39;s marker. <span class="gm-name">GoMeta</span> 0.3.0 ships three content flavors — <code>:julia</code> the default, <code>:c</code> for the <code>//</code> line-comment family, <code>:latex</code> for <code>%</code> — selected explicitly via <code>GoMetaConfig(flavor_tag = …)</code>, never inferred.</p><h2 id="Anatomy" tabindex="-1">Anatomy <a class="header-anchor" href="#Anatomy" aria-label="Permalink to &quot;Anatomy {#Anatomy}&quot;">​</a></h2><p>A metaLine has up to three parts — an optional depth marker, the labels and actions, and an optional human comment:</p><div class="language-gometa vp-adaptive-theme gm-syn"><button title="Copy Code" class="copy"></button><span class="lang">gometa</span><pre class="shiki" tabindex="0"><code><span class="gm-sg">#~</span><span class="gm-mt">[&lt;depth&gt;]  &lt;labels and actions&gt;   </span><span class="gm-cm">## &lt;human comment, ignored by the meta-parser&gt;</span></code></pre></div><ul><li><p>The leading <code>#~</code> (plus optional depth marker), <strong>followed by whitespace or end of line</strong>, identifies the line as meta. An undelimited shape like <code>#~someWord</code> is plain content, not meta — every <span class="gm-name">GoMeta</span> marker token requires whitespace or a line boundary on both sides of its head (the <em>token-delimiter law</em>).</p></li><li><p>The middle carries <strong>labels</strong> (<code>:label1</code>, <code>:label2</code>, …) and <strong>actions</strong> (<code>show{…}</code> / <code>hide{…}</code> / <code>discard{…}</code>), processed left to right.</p></li><li><p>Anything after a <code>##</code> on the same line is a <strong>human comment</strong> — the meta-parser ignores it.</p></li><li><p>If the depth marker is omitted, depth defaults to 1.</p></li></ul><p>A real metaBlock from the committed corpus (<code>examples/InFileFolder/file_for_Example_Extended.jl</code>):</p><div class="language-gometa vp-adaptive-theme gm-syn"><button title="Copy Code" class="copy"></button><span class="lang">gometa</span><pre class="shiki" tabindex="0"><code><span class="gm-sg">#~</span><span class="gm-mt"> discard{ :label2 , isCode} </span><span class="gm-cm">## This is a comment within a meta `Block`.</span>\n<span class="gm-sg">#~</span><span class="gm-mt"> :label1{ isText &amp;&amp; containsMeta }</span>\n<span class="gm-cm">## The following meta `Line` within this `Block` will be ignored due to the `!`.</span>\n<span class="gm-sg">#~!</span><span class="gm-mt"> discard{ isMeta } </span><span class="gm-cm">## This `Line` of meta ends this `Block` of meta.</span></code></pre></div><p><strong>Contiguous metaLines form one metaBlock</strong> — the unit that carries metadata scope. A <code>##</code> comment line <em>between</em> metaLines does not break the block (line 3 above). A metaBlock ends at a blank line, a content line, a <code>#]</code> close-marker, or a <code>#~!</code> — a blank line after a metaLine always starts a new block; only Code and Text blocks may contain interior blank lines.</p><h2 id="Labels" tabindex="-1">Labels <a class="header-anchor" href="#Labels" aria-label="Permalink to &quot;Labels {#Labels}&quot;">​</a></h2><p>Labels are accumulative tags a metaLine applies to the content in its scope — the handles that conditions and actions later select on.</p><ul><li><p>Two equivalent spellings: repeated one-word labels (<code>#~ :label1 :label2</code>) and the parenthesized list (<code>#~ :(label1, label2)</code>).</p></li><li><p>The label vocabulary is a <strong>closed whitelist</strong>: <code>:label1</code> … <code>:label5</code> plus, since 0.3.0, a fixed <strong>pictograph vocabulary</strong> — byte-exact names like <code>:💡</code>, <code>:📝</code>, <code>:🔥</code>. A name from outside the whitelist refuses with a stable message naming the accepted set — whether you <em>apply</em> it or <em>query</em> it in a condition (where the condition is actually evaluated).</p></li><li><p>A <strong>conditional label</strong> applies only where its condition holds: <code>:label1{ isText &amp;&amp; containsMeta }</code> reaches only text that contains meta.</p></li></ul><p>Two different uses of <code>{ … }</code> are worth keeping apart: a <em>label</em>-condition decides <strong>where to apply the label</strong>; an <em>action</em>-condition decides <strong>when to fire the action</strong>.</p><h2 id="Conditions" tabindex="-1">Conditions <a class="header-anchor" href="#Conditions" aria-label="Permalink to &quot;Conditions {#Conditions}&quot;">​</a></h2><p>The <code>{ … }</code> braces carry a condition deciding what an action applies to. Conditions combine <strong>labels</strong> and <strong>State-refs</strong> — the built-in predicates <code>isCode</code>, <code>isText</code>, <code>isMeta</code>, and <code>containsMeta</code> — with <code>,</code> (OR), <code>&amp;&amp;</code> (AND), <code>!</code> (NOT), and <code>()</code> grouping. All four, their meta parts straight from the corpus:</p><div class="language-gometa vp-adaptive-theme gm-syn"><button title="Copy Code" class="copy"></button><span class="lang">gometa</span><pre class="shiki" tabindex="0"><code><span class="gm-sg">#~</span><span class="gm-mt"> discard{ :label2 , isCode}                    </span><span class="gm-cm">## OR — discard what carries :label2 or is code</span>\n<span class="gm-sg">#~</span><span class="gm-mt"> :label1{ isText &amp;&amp; containsMeta }             </span><span class="gm-cm">## AND — a conditional label</span>\n<span class="gm-sg">#~2</span><span class="gm-mt"> :label3 :label5 show{ !:label5}              </span><span class="gm-cm">## NOT — show only if :label5 is absent</span>\n<span class="gm-sg">#~</span><span class="gm-mt"> :label1{ (isText &amp;&amp; containsMeta), isMeta }   </span><span class="gm-cm">## () — grouping, an OR of two groups</span></code></pre></div><p>Precedence of un-parenthesized mixed operators is engine-defined and not exercised by the corpus — make intent unambiguous with explicit <code>()</code>.</p><p>Conditions are <strong>evaluated, never executed</strong> — they run in <span class="gm-name">GoMeta</span>&#39;s own closed interpreter, never through Julia&#39;s <code>eval</code> in a default-configured run.</p><h2 id="The-Visib-actions" tabindex="-1">The Visib actions <a class="header-anchor" href="#The-Visib-actions" aria-label="Permalink to &quot;The Visib actions {#The-Visib-actions}&quot;">​</a></h2><p><strong>Visib</strong> — visibility — is the alterant that decides each component&#39;s fate in a render. Its three actions are mutually exclusive, and the default is <code>show</code>:</p><ul><li><p><code>show</code> → the line is kept <strong>verbatim</strong>;</p></li><li><p><code>hide</code> → the line is kept but <strong>commented out</strong>: every non-empty line gains a <code>##</code> head (a line already starting with <code>##</code> renders as-is; an empty line stays empty);</p></li><li><p><code>discard</code> → the line is <strong>omitted entirely</strong>.</p></li></ul><p>The braces after an action carry a condition, not an argument — Visib actions take no arguments, and a bare <code>hide</code> fires unconditionally. metaLines are themselves subject to Visib: a hidden metaBlock renders as <code>## #~ …</code>. And because hide is a <em>visibility</em> operation, hidden metadata is still alive in the rendered file — choose <code>discard</code> when metadata must not survive a share.</p><h2 id="Depth-and-attachment" tabindex="-1">Depth and attachment <a class="header-anchor" href="#Depth-and-attachment" aria-label="Permalink to &quot;Depth and attachment {#Depth-and-attachment}&quot;">​</a></h2><p>Every metaBlock sits at a <strong>depth</strong> (1, 2, 3, …), analogous to heading levels. The tilde count sets it (<code>#~~~</code> opens depth 3), and a digit sets it too (<code>#~2</code> opens depth 2); with neither, a metaBlock sits at depth 1. The authorable window at v0 is depths 1–8 — <code>#~9</code> meets a stable refusal, not a crash (a multi-digit marker reads its first digit only: <code>#~10</code> behaves as depth 1).</p><p>Depth governs <strong>scope</strong> between metaBlocks: a following metaBlock at depth <em>P</em> <strong>nests inside</strong> an open metaBlock at depth <em>N</em> — and inherits it — when <em>P</em> &gt; <em>N</em>; it <strong>closes/supersedes</strong> it when <em>P</em> ≤ <em>N</em>. The close-marker <code>#]</code> closes the innermost open metaBlock explicitly.</p><p><strong>Attachment</strong> governs what content inherits: a content block is attached to the meta above it exactly when there is <strong>no blank line between them</strong> — an attached block inherits the open metaBlocks&#39; alterants, and a blank line detaches it (it inherits nothing). <code>#]</code> additionally detaches the single line immediately after it. Depth plus attachment govern a metaBlock&#39;s scope — and the two axes are independent.</p><h2 id="Inheritance-—-a-worked-example" tabindex="-1">Inheritance — a worked example <a class="header-anchor" href="#Inheritance-—-a-worked-example" aria-label="Permalink to &quot;Inheritance — a worked example {#Inheritance-—-a-worked-example}&quot;">​</a></h2><p>The toy example below is condensed from the corpus file <code>examples/InFileFolder/file_for_Example_Proposal_JuliaCon.jl</code> — every metaLine&#39;s meta part byte-true, narration comments trimmed or shortened. Its committed rendered counterpart lives in <code>examples/OutFileFolder/</code>.</p><div class="language-gometa vp-adaptive-theme gm-syn"><button title="Copy Code" class="copy"></button><span class="lang">gometa</span><pre class="shiki" tabindex="0"><code><span class="gm-sg">#~</span><span class="gm-mt"> hide{ :label4 , isCode } </span><span class="gm-cm">## This is a comment within a `Block` of meta.</span>\n<span class="gm-sg">#~</span><span class="gm-mt"> :label1{ (isText &amp;&amp; containsMeta), isMeta } </span><span class="gm-cm">## This meta `Block` ends here.</span>\n\n<span class="gm-tx"># This `Line` of text starts a new `Block` of text.</span>\n<span class="gm-tx"># This `Block` is NOT attached to metadata - it does NOT INHERIT metadata.</span>\n<span class="gm-tx"># However, this `Line` will get discarded due to: </span><span class="gm-sg">#~</span><span class="gm-mt"> discard</span>\n\n<span class="gm-sg">#~2</span><span class="gm-mt"> :label5 show{ !:label5} </span><span class="gm-cm">## A one-line meta `Block`.</span>\n<span class="gm-cd">using Plots </span><span class="gm-cm">## This `Line` starts a new `Block` of code.</span>\n\n<span class="gm-cd">println(&quot;!!! NOTE !!! Only Code and Text `Block`s may contain empty lines.&quot;)</span>\n<span class="gm-cd">println(&quot;\\t Whereas an empty line after a meta `Line` starts a new `Block`.&quot;)</span>\n\n<span class="gm-sg">#~3</span><span class="gm-mt"> :label4 discard{:label3} :label3</span>\n<span class="gm-tx"># This `Block` of text receives label4</span>\n<span class="gm-tx">#       plus label5 from further above</span>\n<span class="gm-tx">#       plus label1 since it `isText` AND `containsMeta` [last statement].</span>\n<span class="gm-tx"># This `Line`, however, will NOT get hidden. </span><span class="gm-sg">#~</span><span class="gm-mt"> show</span>\n\n<span class="gm-sg">#~2</span><span class="gm-mt"> :label5</span>\n<span class="gm-tx">md&quot;&quot;&quot;</span>\n<span class="gm-tx">This is a `Block` of markdown text. </span><span class="gm-sg">#~</span><span class="gm-mt"> hide</span>\n<span class="gm-tx">&quot;&quot;&quot;</span></code></pre></div><p>What the render does, and why:</p><ul><li><p><strong>The depth-1 metaBlock</strong> (two contiguous metaLines) issues a conditional action — <code>hide{ :label4 , isCode }</code> — and a conditional label — <code>:label1{ … }</code>. Both now stand over everything that nests or attaches below.</p></li><li><p><strong>The first text block is detached</strong> — the blank line above it severs inheritance — so it renders verbatim… except its last line, whose trailing inline <code>#~ discard</code> removes exactly that line from the render.</p></li><li><p><strong>The <code>#~2</code> metaBlock nests inside depth 1</strong> (2 &gt; 1) and inherits it. The attached code block — <code>using Plots</code> down through both <code>println</code> lines; Code blocks may contain interior blank lines — receives <code>:label5</code>. <code>show{ !:label5}</code> never fires (it needs <code>:label5</code> <em>absent</em>), and the inherited depth-1 <code>hide{ :label4 , isCode }</code> fires because the block is code: the whole block renders commented out.</p></li><li><p><strong>Order matters, left to right.</strong> On <code>#~3 :label4 discard{:label3} :label3</code>, the <code>discard{:label3}</code> is issued <em>before</em> <code>:label3</code> is applied, so it does not fire on the attached text block. The block does receive <code>:label4</code> — and the standing depth-1 <code>hide{ :label4 , isCode }</code> catches it. Its last line ends in inline <code>#~ show</code>, which overrides the inherited hide: that one line stays visible.</p></li><li><p><strong>metaLines are subject to Visib too</strong> — the <code>#~3</code> metaBlock itself renders hidden, as <code>## #~3 …</code>.</p></li><li><p><strong>The markdown line carrying inline <code>#~ hide</code></strong> renders commented out inside the string. <span class="gm-name">GoMeta</span> reads a file as lines — it never lexes the host language&#39;s string syntax.</p></li></ul><h2 id="Three-syntax-forms" tabindex="-1">Three syntax forms <a class="header-anchor" href="#Three-syntax-forms" aria-label="Permalink to &quot;Three syntax forms {#Three-syntax-forms}&quot;">​</a></h2><ul><li><p>the <strong>standard metaLine</strong> on its own line — <code>#~</code>, <code>#~N</code>, <code>#~~~</code>;</p></li><li><p>the <strong>close-marker</strong> <code>#]</code>, closing the innermost open metaBlock (and detaching the single line right after it);</p></li><li><p>the <strong>inline <code>#~</code></strong> at the end of a content line, applying meta to <em>that line</em>: <code>#~ hide</code> / <code>#~ discard</code> hide or discard the line, <code>#~ show</code> overrides an inherited hide, and a bare trailing <code>#~</code> re-applies the meta context to the line.</p></li></ul><p>Plus one modifier: the <strong>inert <code>#~!</code></strong>, which makes a standard metaLine&#39;s content <em>not</em> be processed — it also ends the metaBlock.</p><div class="warning custom-block"><p class="custom-block-title">Writing about <span class="gm-name">GoMeta</span> in comments</p><p>Inside a single-hash <code>#</code> content line, a whitespace-preceded <code>#~</code> token — any form — and <code>#]</code> are parsed as <strong>live inline syntax</strong>, not prose; and a double-hash <code>##</code> comment is <em>not</em> automatically safe either: a whitespace-preceded <code>#~</code> inside one still fires the inline scanner. To mention <span class="gm-name">GoMeta</span> tokens in commentary, <strong>quote-glue</strong> them: write <code>&quot;#~ hide&quot;</code> with the quote hugging the marker. A front-glued marker is never a token — the token-delimiter law again — so the glued mention is inert. The one discipline: no space between the opening quote and the marker (<code>&quot; #~ hide&quot;</code> fires the inline scanner and refuses loudly).</p></div><h2 id="The-full-reference" tabindex="-1">The full reference <a class="header-anchor" href="#The-full-reference" aria-label="Permalink to &quot;The full reference {#The-full-reference}&quot;">​</a></h2><p>This page is a taste. The authoritative, corpus-verified reference — every rule cited to a runnable example and its committed byte-exact render — is <a href="https://github.com/gometa-jl/GoMeta.jl" target="_blank" rel="noreferrer"><code>docs/SYNTAX-AND-SEMANTICS.md</code></a> in the repository, alongside the runnable <code>examples/</code> corpus.</p>',38)])])}const g=a(o,[["render",i]]);export{h as __pageData,g as default};
